/*Table structure for table `contrato` */

CREATE TABLE `contrato` (
  `CONTNUM` varchar(10) NOT NULL,
  `CONTDATINI` datetime DEFAULT NULL,
  `CONTDATFIN` datetime DEFAULT NULL,
  `CONTDATFINEFET` datetime DEFAULT NULL,
  `CODUSU` int(11) NOT NULL,
  PRIMARY KEY (`CONTNUM`),
  UNIQUE KEY `CONTNUM` (`CONTNUM`),
  KEY `CODUSU` (`CODUSU`),
  CONSTRAINT `contrato_ibfk_1` FOREIGN KEY (`CODUSU`) REFERENCES `usuario` (`CODUSU`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

